import type { Quat, Vec3 } from '../contracts/math';

export interface TransformDescriptor {
  position: Vec3;
  rotation?: Quat;
  scale?: Vec3;
}

export type SurfaceMaterial = 'green' | 'rough' | 'sand' | 'ice' | 'wood' | 'stone' | 'metal';

export interface SurfaceDescriptor {
  id: string;
  transform: TransformDescriptor;
  shape: 'box' | 'ramp' | 'cylinder' | 'mesh';
  size: Vec3;
  material: SurfaceMaterial;
  friction?: number;
  restitution?: number;
}

export interface ObstacleBase {
  id: string;
  transform: TransformDescriptor;
  enabled?: boolean;
}

export interface StaticObstacle extends ObstacleBase {
  type: 'wall' | 'bumper' | 'pillar' | 'block';
  size: Vec3;
  restitution?: number;
}

export interface MovingObstacle extends ObstacleBase {
  type: 'spinner' | 'windmill' | 'gate' | 'platform';
  size: Vec3;
  motion: {
    kind: 'rotate' | 'translate';
    axis: Vec3;
    speed: number;
    distance?: number;
    phase?: number;
  };
}

export interface HazardObstacle extends ObstacleBase {
  type: 'water' | 'void' | 'reset-zone';
  size: Vec3;
  penaltyStrokes?: number;
}

export type ObstacleDescriptor = StaticObstacle | MovingObstacle | HazardObstacle;

export interface Hole {
  id: string;
  name: string;
  par: number;
  spawn: Vec3;
  cup: { position: Vec3; radius: number; captureDepth: number };
  bounds: { min: Vec3; max: Vec3 };
  surfaces: SurfaceDescriptor[];
  obstacles: ObstacleDescriptor[];
}

export interface Course {
  id: string;
  name: string;
  themeId: string;
  version: number;
  holes: Hole[];
}
